            "Forgot password?" to "கடவுச்சொல் மறந்துவிட்டதா?",
            "Formatted Doc Report" to "வடிவமைக்கப்பட்ட ஆவண அறிக்கை",
            "Formatted PDF Report" to "வடிவமைக்கப்பட்ட PDF அறிக்கை",
            "Formulas & Worksheets" to "சூத்திரங்கள் & பணித்தாள்கள்",
            "From Order ID" to "ஆர்டர் ஐடியில் இருந்து",
            "FULL NAME" to "முழு பெயர்",
            "GEMINI API KEY" to "ஜெமினி ஏபிஐ கீ",
            "Gemini is unavailable, so I used offline command matching." to "ஜெமினி கிடைக்கவில்லை, அதனால் ஆஃப்லைன் கட்டளை பொருத்தத்தைப் பயன்படுத்தினேன்.",
            "Generated Today" to "இன்று உருவாக்கப்பட்டது",
            "gold-drift" to "தங்க சறுக்கல்",
            "Hi! I'm the ShopFloor Assistant. Ask about employees, sales orders, reports, or app navigation." to "வணக்கம்! நான் கடைநிலை உதவியாளர். ஊழியர்கள், விற்பனை ஆர்டர்கள், அறிக்கைகள் அல்லது பயன்பாட்டு வழிசெலுத்தல் பற்றி கேளுங்கள்.",
            "Highest Progress" to "மிக உயர்ந்த முன்னேற்றம்",
            "Hourly Rate (â‚¹)" to "மணிநேர விகிதம் (â‚¹)",
            "Hourly Rate (â‚¹/hr)" to "மணிநேர வீதம் (â‚¹/hr)",
            "Hours consumed" to "மணிநேரம் நுகரப்படும்",
            "HOURS TRACKING" to "மணிநேர கண்காணிப்பு",
            "How many employees?" to "எத்தனை பணியாளர்கள்?",
            "I can help you find reports, employees, sales orders, departments, costs, and supervisor timers." to "அறிக்கைகள், பணியாளர்கள், விற்பனை ஆர்டர்கள், துறைகள், செலவுகள் மற்றும் மேற்பார்வையாளர் டைமர்களைக் கண்டறிய நான் உங்களுக்கு உதவ முடியும்.",
            "I captured the sales order details. Review every field below, then save or discard it." to "நான் விற்பனை ஆர்டர் விவரங்களைப் பதிவு செய்தேன். கீழே உள்ள ஒவ்வொரு புலத்தையும் மதிப்பாய்வு செய்து, அதைச் சேமிக்கவும் அல்லது நிராகரிக்கவும்.",
            "I couldn't determine a safe action. Mention an exact employee, order, and action, then try again." to "பாதுகாப்பான செயலை என்னால் தீர்மானிக்க முடியவில்லை. சரியான பணியாளர், ஆர்டர் மற்றும் செயலைக் குறிப்பிட்டு, மீண்டும் முயலவும்.",
            "I couldn't find a running sales order to stop." to "நிறுத்துவதற்கான விற்பனை ஆர்டரை என்னால் கண்டுபிடிக்க முடியவில்லை.",
            "I couldn't find employee \$employeeId or sales order \$orderId." to "ஊழியர் \$employeeId அல்லது \$orderId விற்பனை ஆர்டரை என்னால் கண்டுபிடிக்க முடியவில்லை.",
            "I couldn't find sales order \$targetOrder." to "\$targetOrder என்ற விற்பனை ஆர்டரை என்னால் கண்டுபிடிக்க முடியவில்லை.",
            "I couldn't find that order or any assigned employee." to "அந்த ஆர்டரையோ அல்லது ஒதுக்கப்பட்ட பணியாளரையோ என்னால் கண்டுபிடிக்க முடியவில்லை.",
            "I couldn't hear a complete command. Please try again." to "என்னால் முழுமையான கட்டளையைக் கேட்க முடியவில்லை. மீண்டும் முயற்சிக்கவும்.",
            "I couldn't match that department." to "என்னால் அந்தத் துறையைப் பொருத்த முடியவில்லை.",
            "I couldn't match that employee exactly. Use their full name or employee ID." to "அந்த ஊழியரை என்னால் சரியாகப் பொருத்த முடியவில்லை. அவர்களின் முழுப் பெயர் அல்லது பணியாளர் ஐடியைப் பயன்படுத்தவும்.",
            "I couldn't match that existing sales order." to "தற்போதுள்ள விற்பனை வரிசையை என்னால் பொருத்த முடியவில்லை.",
            "I couldn't match that labour category." to "அந்த தொழிலாளர் வகையை என்னால் பொருத்த முடியவில்லை.",
            "I couldn't match that sales order and its assigned employees." to "அந்த விற்பனை ஆர்டரையும் அதற்கு ஒதுக்கப்பட்ட ஊழியர்களையும் என்னால் பொருத்த முடியவில்லை.",
            "I couldn't match the employee and destination order exactly." to "பணியாளர் மற்றும் சேருமிட ஆர்டரை என்னால் சரியாகப் பொருத்த முடியவில்லை.",
            "I couldn't match the existing employee and sales order exactly." to "தற்போதுள்ள ஊழியர் மற்றும் விற்பனை வரிசையை என்னால் சரியாகப் பொருத்த முடியவில்லை.",
            "I couldn't transcribe that recording. Check the Sarvam key and network, then try again." to "அந்தப் பதிவை என்னால் எழுத முடியவில்லை. சர்வம் விசை மற்றும் நெட்வொர்க்கைச் சரிபார்த்து, மீண்டும் முயற்சிக்கவும்.",
            "I don't have enough live data to answer that." to "அதற்குப் பதிலளிக்க என்னிடம் போதுமான நேரடி தரவு இல்லை.",
            "I found \${employee.name}'s assignment. Review your changes below, then save it." to "\${employee.name} இன் வேலையைக் கண்டேன். கீழே உங்கள் மாற்றங்களைச் சரிபார்த்து, அதைச் சேமிக்கவும்.",
