            "I can help you find reports, employees, sales orders, departments, costs, and supervisor timers." to "నివేదికలు, ఉద్యోగులు, సేల్స్ ఆర్డర్‌లు, విభాగాలు, ఖర్చులు మరియు సూపర్‌వైజర్ టైమర్‌లను కనుగొనడంలో నేను మీకు సహాయం చేయగలను.",
            "I captured the sales order details. Review every field below, then save or discard it." to "నేను సేల్స్ ఆర్డర్ వివరాలను క్యాప్చర్ చేసాను. దిగువన ఉన్న ప్రతి ఫీల్డ్‌ను సమీక్షించండి, ఆపై దాన్ని సేవ్ చేయండి లేదా విస్మరించండి.",
            "I couldn't determine a safe action. Mention an exact employee, order, and action, then try again." to "నేను సురక్షితమైన చర్యను గుర్తించలేకపోయాను. ఖచ్చితమైన ఉద్యోగి, ఆర్డర్ మరియు చర్యను పేర్కొనండి, ఆపై మళ్లీ ప్రయత్నించండి.",
            "I couldn't find a running sales order to stop." to "నేను ఆపడానికి నడుస్తున్న సేల్స్ ఆర్డర్‌ని కనుగొనలేకపోయాను.",
            "I couldn't find employee \$employeeId or sales order \$orderId." to "నేను ఉద్యోగి \$employeeId లేదా సేల్స్ ఆర్డర్ \$orderIdని కనుగొనలేకపోయాను.",
            "I couldn't find sales order \$targetOrder." to "నేను \$targetOrder సేల్స్ ఆర్డర్‌ని కనుగొనలేకపోయాను.",
            "I couldn't find that order or any assigned employee." to "నేను ఆ ఆర్డర్‌ను లేదా కేటాయించిన ఉద్యోగిని కనుగొనలేకపోయాను.",
            "I couldn't hear a complete command. Please try again." to "నేను పూర్తి ఆదేశాన్ని వినలేకపోయాను. దయచేసి మళ్లీ ప్రయత్నించండి.",
            "I couldn't match that department." to "నేను ఆ విభాగానికి సరిపోలలేదు.",
