            "Gemini is unavailable, so I used offline command matching." to "ಜೆಮಿನಿ ಲಭ್ಯವಿಲ್ಲ, ಆದ್ದರಿಂದ ನಾನು ಆಫ್‌ಲೈನ್ ಕಮಾಂಡ್ ಹೊಂದಾಣಿಕೆಯನ್ನು ಬಳಸಿದ್ದೇನೆ.",
            "Generated Today" to "ಇಂದು ರಚಿಸಲಾಗಿದೆ",
            "gold-drift" to "ಚಿನ್ನದ-ಡ್ರಿಫ್ಟ್",
            "Hi! I'm the ShopFloor Assistant. Ask about employees, sales orders, reports, or app navigation." to "ನಮಸ್ಕಾರ! ನಾನು ಶಾಪ್‌ಫ್ಲೋರ್ ಸಹಾಯಕ. ಉದ್ಯೋಗಿಗಳು, ಮಾರಾಟ ಆದೇಶಗಳು, ವರದಿಗಳು ಅಥವಾ ಅಪ್ಲಿಕೇಶನ್ ನ್ಯಾವಿಗೇಷನ್ ಬಗ್ಗೆ ಕೇಳಿ.",
            "Highest Progress" to "ಅತ್ಯಧಿಕ ಪ್ರಗತಿ",
            "Hourly Rate (â‚¹)" to "ಗಂಟೆಯ ದರ (â‚¹)",
            "Hourly Rate (â‚¹/hr)" to "ಗಂಟೆಯ ದರ (â‚¹/hr)",
            "Hours consumed" to "ಗಂಟೆಗಳನ್ನು ಸೇವಿಸಲಾಗಿದೆ",
            "HOURS TRACKING" to "ಗಂಟೆಗಳ ಟ್ರ್ಯಾಕಿಂಗ್",
            "How many employees?" to "ಎಷ್ಟು ಉದ್ಯೋಗಿಗಳು?",
            "I can help you find reports, employees, sales orders, departments, costs, and supervisor timers." to "ವರದಿಗಳು, ಉದ್ಯೋಗಿಗಳು, ಮಾರಾಟ ಆದೇಶಗಳು, ಇಲಾಖೆಗಳು, ವೆಚ್ಚಗಳು ಮತ್ತು ಮೇಲ್ವಿಚಾರಕ ಟೈಮರ್‌ಗಳನ್ನು ಹುಡುಕಲು ನಾನು ನಿಮಗೆ ಸಹಾಯ ಮಾಡಬಲ್ಲೆ.",
            "I captured the sales order details. Review every field below, then save or discard it." to "ನಾನು ಮಾರಾಟದ ಆದೇಶದ ವಿವರಗಳನ್ನು ಸೆರೆಹಿಡಿದಿದ್ದೇನೆ. ಕೆಳಗಿನ ಪ್ರತಿಯೊಂದು ಕ್ಷೇತ್ರವನ್ನು ಪರಿಶೀಲಿಸಿ, ನಂತರ ಅದನ್ನು ಉಳಿಸಿ ಅಥವಾ ತ್ಯಜಿಸಿ.",
            "I couldn't determine a safe action. Mention an exact employee, order, and action, then try again." to "ಸುರಕ್ಷಿತ ಕ್ರಮವನ್ನು ನಿರ್ಧರಿಸಲು ನನಗೆ ಸಾಧ್ಯವಾಗಲಿಲ್ಲ. ನಿಖರವಾದ ಉದ್ಯೋಗಿ, ಆದೇಶ ಮತ್ತು ಕ್ರಮವನ್ನು ಉಲ್ಲೇಖಿಸಿ, ನಂತರ ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.",
            "I couldn't find a running sales order to stop." to "ನಿಲ್ಲಿಸಲು ನನಗೆ ಚಾಲನೆಯಲ್ಲಿರುವ ಮಾರಾಟದ ಆದೇಶವನ್ನು ಕಂಡುಹಿಡಿಯಲಾಗಲಿಲ್ಲ.",
            "I couldn't find employee \$employeeId or sales order \$orderId." to "ಉದ್ಯೋಗಿ \$employeeId ಅಥವಾ ಮಾರಾಟದ ಆದೇಶ \$orderId ಅನ್ನು ಹುಡುಕಲು ನನಗೆ ಸಾಧ್ಯವಾಗಲಿಲ್ಲ.",
            "I couldn't find sales order \$targetOrder." to "ನನಗೆ \$targetOrder ಮಾರಾಟದ ಆದೇಶವನ್ನು ಕಂಡುಹಿಡಿಯಲಾಗಲಿಲ್ಲ.",
            "I couldn't find that order or any assigned employee." to "ನನಗೆ ಆ ಆದೇಶ ಅಥವಾ ಯಾವುದೇ ನಿಯೋಜಿತ ಉದ್ಯೋಗಿಯನ್ನು ಹುಡುಕಲಾಗಲಿಲ್ಲ.",
            "I couldn't hear a complete command. Please try again." to "ನನಗೆ ಸಂಪೂರ್ಣ ಆಜ್ಞೆಯನ್ನು ಕೇಳಲಾಗಲಿಲ್ಲ. ದಯವಿಟ್ಟು ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.",
            "I couldn't match that department." to "ನನಗೆ ಆ ವಿಭಾಗವನ್ನು ಹೊಂದಿಸಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ.",
            "I couldn't match that employee exactly. Use their full name or employee ID." to "ನಾನು ಆ ಉದ್ಯೋಗಿಯನ್ನು ನಿಖರವಾಗಿ ಹೊಂದಿಸಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ. ಅವರ ಪೂರ್ಣ ಹೆಸರು ಅಥವಾ ಉದ್ಯೋಗಿ ಐಡಿ ಬಳಸಿ.",
            "I couldn't match that existing sales order." to "ಅಸ್ತಿತ್ವದಲ್ಲಿರುವ ಮಾರಾಟದ ಆದೇಶವನ್ನು ನಾನು ಹೊಂದಿಸಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ.",
            "I couldn't match that labour category." to "ನಾನು ಆ ಕಾರ್ಮಿಕ ವರ್ಗವನ್ನು ಹೊಂದಿಸಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ.",
            "I couldn't match that sales order and its assigned employees." to "ನನಗೆ ಆ ಮಾರಾಟದ ಆದೇಶ ಮತ್ತು ಅದರ ನಿಯೋಜಿತ ಉದ್ಯೋಗಿಗಳನ್ನು ಹೊಂದಿಸಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ.",
            "I couldn't match the employee and destination order exactly." to "ಉದ್ಯೋಗಿ ಮತ್ತು ಗಮ್ಯಸ್ಥಾನದ ಆದೇಶವನ್ನು ನಿಖರವಾಗಿ ಹೊಂದಿಸಲು ನನಗೆ ಸಾಧ್ಯವಾಗಲಿಲ್ಲ.",
            "I couldn't match the existing employee and sales order exactly." to "ಅಸ್ತಿತ್ವದಲ್ಲಿರುವ ಉದ್ಯೋಗಿ ಮತ್ತು ಮಾರಾಟದ ಆದೇಶವನ್ನು ನಿಖರವಾಗಿ ಹೊಂದಿಸಲು ನನಗೆ ಸಾಧ್ಯವಾಗಲಿಲ್ಲ.",
            "I couldn't transcribe that recording. Check the Sarvam key and network, then try again." to "ನನಗೆ ಆ ರೆಕಾರ್ಡಿಂಗ್ ಅನ್ನು ಲಿಪ್ಯಂತರ ಮಾಡಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ. ಸರ್ವಂ ಕೀ ಮತ್ತು ನೆಟ್‌ವರ್ಕ್ ಅನ್ನು ಪರಿಶೀಲಿಸಿ, ನಂತರ ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.",
            "I don't have enough live data to answer that." to "ಅದಕ್ಕೆ ಉತ್ತರಿಸಲು ನನ್ನ ಬಳಿ ಸಾಕಷ್ಟು ಲೈವ್ ಡೇಟಾ ಇಲ್ಲ.",
            "I found \${employee.name}'s assignment. Review your changes below, then save it." to "ನಾನು \${employee.name} ಅವರ ನಿಯೋಜನೆಯನ್ನು ಕಂಡುಕೊಂಡಿದ್ದೇನೆ. ನಿಮ್ಮ ಬದಲಾವಣೆಗಳನ್ನು ಕೆಳಗೆ ಪರಿಶೀಲಿಸಿ, ನಂತರ ಅದನ್ನು ಉಳಿಸಿ.",
            "I matched \${employee.name} and \${order.id}. Review and save the assignment below." to "ನಾನು \${employee.name} ಮತ್ತು \${order.id} ಗೆ ಹೊಂದಿಕೆಯಾಗಿದ್ದೇನೆ. ಕೆಳಗಿನ ನಿಯೋಜನೆಯನ್ನು ಪರಿಶೀಲಿಸಿ ಮತ್ತು ಉಳಿಸಿ.",
            "I understood this as \${result.type.replace(" to "ನಾನು ಇದನ್ನು \${result.type.replace( ಎಂದು ಅರ್ಥಮಾಡಿಕೊಂಡಿದ್ದೇನೆ.",
            "ID: \$empId â€¢ Dept: \${employee.department} â€¢ Cat: \${employee.category}" to "ID: \$empId â€¢ ಇಲಾಖೆ: \${employee.department} â€¢ ಬೆಕ್ಕು: \${employee.category}",
