            "Hi! I'm the ShopFloor Assistant. Ask about employees, sales orders, reports, or app navigation." to "ഹായ്! ഞാൻ ഷോപ്പ് ഫ്ലോർ അസിസ്റ്റൻ്റാണ്. ജീവനക്കാർ, വിൽപ്പന ഓർഡറുകൾ, റിപ്പോർട്ടുകൾ അല്ലെങ്കിൽ ആപ്പ് നാവിഗേഷൻ എന്നിവയെക്കുറിച്ച് ചോദിക്കുക.",
