            "How many employees?" to "എത്ര ജീവനക്കാർ?",
            "I can help you find reports, employees, sales orders, departments, costs, and supervisor timers." to "റിപ്പോർട്ടുകൾ, ജീവനക്കാർ, സെയിൽസ് ഓർഡറുകൾ, വകുപ്പുകൾ, ചെലവുകൾ, സൂപ്പർവൈസർ ടൈമറുകൾ എന്നിവ കണ്ടെത്താൻ എനിക്ക് നിങ്ങളെ സഹായിക്കാനാകും.",
            "I captured the sales order details. Review every field below, then save or discard it." to "ഞാൻ വിൽപ്പന ഓർഡർ വിശദാംശങ്ങൾ പിടിച്ചെടുത്തു. ചുവടെയുള്ള എല്ലാ ഫീൽഡുകളും അവലോകനം ചെയ്യുക, തുടർന്ന് അത് സംരക്ഷിക്കുക അല്ലെങ്കിൽ ഉപേക്ഷിക്കുക.",
            "I couldn't determine a safe action. Mention an exact employee, order, and action, then try again." to "എനിക്ക് ഒരു സുരക്ഷിത പ്രവർത്തനം നിർണ്ണയിക്കാൻ കഴിഞ്ഞില്ല. ഒരു കൃത്യമായ ജീവനക്കാരനെ പരാമർശിക്കുക, ഓർഡർ, നടപടി, തുടർന്ന് വീണ്ടും ശ്രമിക്കുക.",
            "I couldn't find a running sales order to stop." to "നിർത്താൻ എനിക്ക് റണ്ണിംഗ് സെയിൽസ് ഓർഡർ കണ്ടെത്താനായില്ല.",
            "I couldn't find employee \$employeeId or sales order \$orderId." to "എനിക്ക് ജീവനക്കാരനായ \$employeeId അല്ലെങ്കിൽ \$orderId വിൽപ്പന ഓർഡർ കണ്ടെത്താൻ കഴിഞ്ഞില്ല.",
            "I couldn't find sales order \$targetOrder." to "എനിക്ക് \$targetOrder വിൽപ്പന ഓർഡർ കണ്ടെത്താൻ കഴിഞ്ഞില്ല.",
            "I couldn't find that order or any assigned employee." to "എനിക്ക് ആ ഓർഡറോ അസൈൻ ചെയ്ത ജീവനക്കാരനെയോ കണ്ടെത്താൻ കഴിഞ്ഞില്ല.",
            "I couldn't hear a complete command. Please try again." to "എനിക്ക് പൂർണ്ണമായ ഒരു കമാൻഡ് കേൾക്കാനായില്ല. ദയവായി വീണ്ടും ശ്രമിക്കുക.",
            "I couldn't match that department." to "എനിക്ക് ആ വകുപ്പുമായി പൊരുത്തപ്പെടാൻ കഴിഞ്ഞില്ല.",
            "I couldn't match that employee exactly. Use their full name or employee ID." to "എനിക്ക് ആ ജീവനക്കാരനെ കൃത്യമായി പൊരുത്തപ്പെടുത്താൻ കഴിഞ്ഞില്ല. അവരുടെ മുഴുവൻ പേരോ ജീവനക്കാരുടെ ഐഡിയോ ഉപയോഗിക്കുക.",
            "I couldn't match that existing sales order." to "നിലവിലുള്ള വിൽപ്പന ക്രമവുമായി പൊരുത്തപ്പെടാൻ എനിക്ക് കഴിഞ്ഞില്ല.",
            "I couldn't match that labour category." to "എനിക്ക് ആ തൊഴിൽ വിഭാഗവുമായി പൊരുത്തപ്പെടാൻ കഴിഞ്ഞില്ല.",
