    private data class TemplateTranslation(val regex: Regex, val translated: String)
    private val placeholder = Regex("\\$\\{[^}]+\\}|\\$[A-Za-z_][A-Za-z0-9_]*")
    private val templates: Map<String, List<TemplateTranslation>> by lazy {
        translations.mapValues { (_, dictionary) ->
            dictionary.entries.filter { (source, translated) ->
                val sourcePlaceholders = placeholder.findAll(source).map { it.value }.sorted().toList()
                val translatedPlaceholders = placeholder.findAll(translated).map { it.value }.sorted().toList()
                sourcePlaceholders.isNotEmpty() && sourcePlaceholders == translatedPlaceholders
            }.map { (source, translated) ->
                val pattern = StringBuilder("^")
                var cursor = 0
                placeholder.findAll(source).forEach { match ->
                    pattern.append(Regex.escape(source.substring(cursor, match.range.first))).append("(.*?)")
                    cursor = match.range.last + 1
                }
                pattern.append(Regex.escape(source.substring(cursor))).append('$')
                TemplateTranslation(Regex(pattern.toString()), translated)
            }
        }
    }

    fun translate(languageTag: String, text: String): String {
        val dictionary = translations[languageTag] ?: return text
        dictionary[text]?.let { return it }
        templates[languageTag].orEmpty().forEach { template ->
            val match = template.regex.matchEntire(text) ?: return@forEach
            var captureIndex = 1
            return placeholder.replace(template.translated) {
                match.groupValues.getOrElse(captureIndex++) { "" }
            }
        }
        return text
    }
}
